function naLista(lista, pedidos) {
  let achados = 0;
  for (const pedido of pedidos) {
    if (lista.includes(pedido)) achados++;
  }
  return achados;
}
function noMapa(lista, pedidos) {
  const mapa = new Map();
  for (const item of lista) mapa.set(item, true);
  let achados = 0;
  for (const pedido of pedidos) {
    const existe = mapa.has(pedido);
    if (existe) achados++;
  }
  return achados;
}
const achados = noMapa([4,8,12], [8,99,4]);
console.log(naLista([4,8,12], [8,99,4]), achados);

