function conferir(lista) {
  const vistos = new Map();
  let repetidos = 0;
  for (const codigo of lista) {
    const existe = vistos.has(codigo);
    if (existe) repetidos++;
    else vistos.set(codigo, true);
  }
  return repetidos;
}
